/**
 * Failure analysis + correction. Kept deliberately small (self-healing is not a core goal):
 *   1. an LLM triages the failure into a category;
 *   2. only fixable categories trigger regeneration — real application defects and environment
 *      problems are surfaced for human review instead of being "healed" away.
 *
 * Web specs are regenerated by resuming the authoring agent from the last working step
 * (see ../web/author.ts). API specs get corrected expectations/requests from a structured model
 * answer. Triage prompt shape follows ai-testing-agent's failure analyser (MIT): root cause,
 * likely category, recommended fix.
 */
import type { Browser } from "playwright";
import { z } from "zod";
import { withStatedSources } from "../api/stated-source.js";
import type { EngineContext } from "../context.js";
import { jsonText, pairs, recordOf } from "../llm/free-keys.js";
import type { KnowledgeRule } from "../planning/planner.js";
import { StepSchema, type Scenario, type Step, type TestSpec } from "../spec/schema.js";
import type { AppModel } from "../understanding/app-model.js";
import { authorWebSpec, statedSource, statedSourceText } from "../web/author.js";
import type { ScriptRun } from "./runner.js";

export const TriageSchema = z.object({
    category: z.enum(["locator", "timing", "test_data", "assertion", "app_defect", "environment", "other"]),
    fixable: z.boolean().describe("true if the TEST is wrong and can be corrected; false if the application or environment is at fault"),
    reason: z.string().describe("One or two sentences, factual"),
    firstWrongStep: z
        .number()
        .int()
        .min(1)
        .optional()
        .describe("1-based number of the FIRST step that is wrong, if it is earlier than the step that failed (e.g. a stray navigation or duplicated actions before the failure)"),
});

export interface Repair {
    verdict: "fixed" | "app_defect" | "unfixable";
    reason: string;
    spec?: TestSpec;
}

function failureText(spec: TestSpec, run: ScriptRun): string {
    const failed = run.steps.find((s) => s.status === "failed");
    return [
        `Status: ${run.status}`,
        failed ? `Failed step: ${failed.title}` : "No individual step failed (timeout, setup or syntax problem).",
        `Error: ${(failed?.error ?? run.error ?? "unknown").slice(0, 1200)}`,
        // What the page showed at the failing check (Playwright's error context): the elements really there, with their names.
        ...(run.errorContext ? [`What the page showed when it failed (accessibility snapshot):\n${run.errorContext.slice(0, 4000)}`] : []),
    ].join("\n");
}

export async function triage(ctx: EngineContext, spec: TestSpec, run: ScriptRun) {
    return ctx.llm.object({
        system: `You analyse why an automatically generated end-to-end/API test failed when executed.
Decide whether the TEST is wrong (bad locator, race condition, wrong test data, wrong expectation) or whether the APPLICATION/ENVIRONMENT is at fault
(feature broken, server error, network/DNS problem, blocked by captcha/bot protection). Be conservative: only mark fixable=true if a test change would plausibly make it pass.`,
        prompt: `Test: ${spec.testId} ${spec.title} (${spec.kind})
Expected results: ${spec.expectedResults.join("; ") || "n/a"}
Steps:
${spec.steps.map((s, i) => `${i + 1}. ${JSON.stringify(s)}`).join("\n")}

${failureText(spec, run)}`,
        schema: TriageSchema,
        maxOutputTokens: 600,
        purpose: "repair",
    });
}

export async function repairWeb(args: {
    ctx: EngineContext;
    browser: Browser;
    baseUrl: string;
    model: AppModel;
    scenario: Scenario;
    spec: TestSpec;
    run: ScriptRun;
    credentials?: { username: string; password: string };
    /** 1-based repair attempt for this test. Later attempts re-author from scratch. */
    attempt?: number;
    /** The run's known secrets: what the app shows in the browser while the test is re-authored is masked with them. */
    secrets?: readonly string[];
    /** The scenario's rules: the re-written test still checks them (a repair fixes how a test checks, never what it must check). */
    rules?: KnowledgeRule[];
    /** The ids of the job's requirements: an expected result naming one the scenario covers is stated (author.ts statedSource). */
    requirementIds?: readonly string[];
    /** The project allows tests that change data: the re-written test may place orders and pay with test data (row 206). */
    allowPurchases?: boolean;
}): Promise<Repair> {
    const { ctx, spec, run } = args;
    const t = await triage(ctx, spec, run);
    ctx.emit({
        stage: "validation",
        kind: "failure_analyzed",
        level: "warn",
        message: `${spec.testId} failed (${t.category}): ${t.reason}`,
        data: { testId: spec.testId, category: t.category, fixable: t.fixable },
    });
    if (t.category === "app_defect" || t.category === "environment" || !t.fixable) {
        return { verdict: t.category === "app_defect" ? "app_defect" : "unfixable", reason: t.reason };
    }
    // A failing check of a STATED source is a stated expectation the app does not meet: never "fixed" by re-writing the test (roadmap 2.4).
    // Stated as the author decides it (statedSource, queue row 182): a check of the planner's own expected result is not, so triage's
    // verdict stands and a fixable failure is repaired (C1c's WEB-037: wrong test data reported as an app defect).
    const failedStep = run.failedStepIndex >= 0 ? spec.steps[run.failedStepIndex] : undefined;
    if (failedStep?.action === "assert" && failedStep.source && statedSource(failedStep.source, args.scenario, args.rules, args.requirementIds)) {
        // Row 229 (1c): when triage says the test's data or expectation is wrong and the check expects an amount or a record id its stated
        // source does not give (a total or an order number read from what the account held), the value is the test's, not the source's:
        // triage's verdict stands and the test is repaired like any other (row 227: WEB-055, 056, 060 and C1e's WEB-028).
        const computed = TEST_FAULTS.has(t.category) ? unstatedComputedValue(failedStep, statedSourceText(failedStep.source, args.scenario, args.rules)) : undefined;
        // Triage read the test's data or expectation as wrong (WEB-002: "the app is sorting correctly"): still a finding of the stated
        // check, but its reason says so, and verification never confirms it on the vote alone (verify-service.ts).
        const disputed = TEST_FAULTS.has(t.category) ? `, but ${ANALYSIS_BLAMES_TEST} (${t.category})` : "";
        if (computed === undefined) return { verdict: "app_defect", reason: `a stated expectation is not met (${failedStep.source})${disputed}: ${t.reason}` };
        ctx.emit({
            stage: "validation",
            kind: "computed_value_test_fault",
            level: "warn",
            message: `${spec.testId}: the failing check of ${failedStep.source} expects ${computed}, which its stated source does not give, so the test is repaired, not reported as a defect`,
            data: { testId: spec.testId, source: failedStep.source, category: t.category },
        });
    }

    // Keep the steps before the first *wrong* one — which can be earlier than the failing step (a stray
    // navigation that still "works" only breaks a later assertion). If a resumed repair already failed,
    // re-author from scratch instead of rebuilding on the same prefix.
    const failedAt = run.failedStepIndex >= 0 ? run.failedStepIndex : 1;
    const wrongAt = t.firstWrongStep !== undefined ? t.firstWrongStep - 1 : failedAt;
    const cut = (args.attempt ?? 1) > 1 ? 1 : Math.min(failedAt, wrongAt);
    const prefix = spec.steps.slice(0, Math.max(1, cut));
    const outcome = await authorWebSpec({
        ctx,
        browser: args.browser,
        baseUrl: args.baseUrl,
        model: args.model,
        scenario: args.scenario,
        credentials: args.credentials,
        ...(args.secrets ? { secrets: [...args.secrets] } : {}),
        ...(args.rules?.length ? { rules: args.rules } : {}),
        ...(args.requirementIds?.length ? { requirementIds: args.requirementIds } : {}),
        ...(args.allowPurchases ? { allowPurchases: true } : {}),
        resume: { prefix, failure: failureText(spec, run) },
    });
    if (outcome.status === "complete") {
        const rejected = weakensWebTest(spec, outcome.steps);
        if (rejected) {
            ctx.emit({ stage: "validation", kind: "repair_rejected", level: "warn", message: `${spec.testId}: proposed fix rejected — ${rejected}` });
            return { verdict: "unfixable", reason: `${t.reason} (proposed fix rejected: ${rejected})` };
        }
        return { verdict: "fixed", reason: t.reason, spec: { ...spec, steps: outcome.steps, testData: { ...spec.testData, ...outcome.testData } } };
    }
    if (outcome.status === "defect") return { verdict: "app_defect", reason: outcome.explanation };
    return { verdict: "unfixable", reason: outcome.explanation };
}

/** The words a stated check's finding carries when the failure analysis says the test, not the application, is wrong. */
export const ANALYSIS_BLAMES_TEST = "the failure analysis reads the test as wrong";
/** Triage categories that say the test is wrong, not the application: its data or its expected result. */
const TEST_FAULTS: ReadonlySet<string> = new Set(["test_data", "assertion"]);
/** An amount as written on a page: a currency sign next to a number, or a number with two decimals ($664.99, 1,234.50, 12,50 €). */
const AMOUNT = /[$€£¥₹]\s?\d(?:[\d,.]*\d)?|\d[\d,]*[.,]\d{2}(?!\d)/g;
/** A record id the application numbers (ord-1008, INV-20031). */
const RECORD_ID = /\b[a-z]{2,}-\d{3,}\b/gi;
/** An amount compared by its value (thousands separators, currency and sign dropped): "$1,234.50", "1234.5" and "1.234,50 €" are one, "$5" and "5.00" too. */
const amountKey = (a: string) => {
    const digits = a.replace(/[^\d.,]/g, "");
    const m = /^(.*?)[.,](\d{2})$/.exec(digits);
    return String(Number(m ? `${m[1]!.replace(/[.,]/g, "")}.${m[2]}` : digits.replace(/[.,]/g, "")));
};

/**
 * The first amount or record id a check expects (its expected value, or the text its locator looks for) that `stated` (the words of its
 * stated source, statedSourceText) does not give; undefined when it expects none, or every one is stated. A check that something is
 * absent (notText, hidden) expects no value. Row 229 (1c).
 */
export function unstatedComputedValue(step: AssertStep, stated: string): string | undefined {
    if (step.check === "notText" || step.check === "hidden") return undefined;
    const said = [step.expected, step.locator?.by === "text" ? step.locator.value : undefined, step.locator?.filter?.hasText].filter((v): v is string => typeof v === "string");
    const amounts = new Set([...stated.matchAll(AMOUNT)].map((m) => amountKey(m[0])));
    const ids = new Set([...stated.matchAll(RECORD_ID)].map((m) => m[0].toLowerCase()));
    for (const text of said) {
        for (const m of text.matchAll(RECORD_ID)) if (!ids.has(m[0].toLowerCase())) return m[0];
        for (const m of text.matchAll(AMOUNT)) if (!amounts.has(amountKey(m[0]))) return m[0];
    }
    return undefined;
}

type StepMember<A extends string> = Extract<(typeof StepSchema.options)[number], { shape: { action: z.ZodLiteral<A> } }>;
const stepOf = <A extends "request" | "assertResponse">(action: A) => StepSchema.options.find((o) => o.shape.action.value === action)! as StepMember<A>;
/**
 * An API test's steps (requests and response checks), defined and validated by StepSchema's own members. The repair answer asks for these
 * only: with every step kind the schema had 437 optional parameters and Anthropic refuses more than 24 (tests/llm-schema-limits-unit.test.ts).
 */
const ApiStepSchema = z.discriminatedUnion("action", [stepOf("request"), stepOf("assertResponse")]);
/**
 * The same steps as the model answers them: a request's query, headers and extract as { name, value } pairs, its body and a matchesSchema
 * check's schema as JSON text, because a grammar-constrained answer can only give {} for an object whose keys are not listed
 * (llm/free-keys.ts). stepOfAnswer turns each one back into the test's step.
 */
const ApiStepAnswerSchema = z.discriminatedUnion("action", [
    stepOf("request").extend({
        query: pairs(z.string()).optional(),
        headers: pairs(z.string()).optional(),
        extract: pairs(z.string()).optional().describe('Values to capture from the JSON answer: [{"name": "productId", "value": "0.id"}]'),
        body: jsonText(20_000).optional().describe("The JSON body, as text"),
    }),
    stepOf("assertResponse").extend({ schema: jsonText(20_000, true).optional().describe("matchesSchema only: the documented response schema, as JSON text") }),
]);
export const ApiRepairSchema = z.object({
    verdict: z.enum(["fix", "app_defect", "unfixable"]),
    reason: z.string(),
    steps: z.array(ApiStepAnswerSchema).optional().describe("Complete replacement step list when verdict=fix"),
});

/** An answered step as the test's step: pairs become objects, JSON text is parsed, and StepSchema's own member validates the result. */
function stepOfAnswer(s: z.infer<typeof ApiStepAnswerSchema>): Step {
    if (s.action === "request") {
        const { query, headers, extract, body, ...rest } = s;
        const records = { query, headers, extract };
        const objects = Object.fromEntries(Object.entries(records).flatMap(([k, v]) => (v ? [[k, recordOf(v)]] : [])));
        return ApiStepSchema.parse({ ...rest, ...objects, ...(body !== undefined ? { body: JSON.parse(body) } : {}) }) as Step;
    }
    const { schema, ...rest } = s;
    return ApiStepSchema.parse({ ...rest, ...(schema !== undefined ? { schema: JSON.parse(schema) } : {}) }) as Step;
}

export async function repairApi(ctx: EngineContext, spec: TestSpec, run: ScriptRun, endpointDoc: unknown): Promise<Repair> {
    const t = await triage(ctx, spec, run);
    ctx.emit({
        stage: "validation",
        kind: "failure_analyzed",
        level: "warn",
        message: `${spec.testId} failed (${t.category}): ${t.reason}`,
        data: { testId: spec.testId, category: t.category, fixable: t.fixable },
    });
    if (t.category === "environment") return { verdict: "unfixable", reason: t.reason };

    const out = await ctx.llm.object({
        system: `You correct a failing API test. The test was generated from an API description and executed against the real service.
If the service legitimately behaves differently from what the test assumed (e.g. returns 422 instead of 400, a different status class, a different body shape), correct the test's request/assertions to match the real behaviour **only when that behaviour is reasonable and not a security or correctness defect**.
If the service behaves in a way that is a real defect (5xx on bad input, unauthenticated access allowed, injection reflected), answer verdict=app_defect and keep the test unchanged.
Never loosen an assertion just to make it pass.
In your answer, a request's query, headers and extract are lists of { name, value } pairs, and its body (and a matchesSchema check's schema) is JSON text.`,
        prompt: `Spec:
${JSON.stringify({ title: spec.title, steps: spec.steps, expectedResults: spec.expectedResults }, null, 1)}

Endpoint documentation:
${JSON.stringify(endpointDoc ?? null).slice(0, 3000)}

${failureText(spec, run)}

Triage: ${t.category} — ${t.reason}`,
        schema: ApiRepairSchema,
        maxOutputTokens: 3000,
        purpose: "repair",
    });

    if (out.verdict === "fix" && out.steps?.length) {
        const proposed = keepRecords(spec.steps, out.steps.map(stepOfAnswer));
        const rejected = weakensApiTest(spec, proposed);
        if (rejected) {
            ctx.emit({ stage: "validation", kind: "repair_rejected", level: "warn", message: `${spec.testId}: proposed fix rejected — ${rejected}` });
            return { verdict: "unfixable", reason: `${t.reason} (proposed fix rejected: ${rejected})` };
        }
        // The answer's steps name no source: the API document, standard rule or requirement the checks cite is put back as generation
        // gives it (API-084: without it a documented 409 read as the planner's guess and the finding as an incorrect expectation).
        const repaired = { ...spec, steps: proposed };
        const doc = endpointDoc as { method?: unknown; path?: unknown; spec?: { responses?: unknown } } | null | undefined;
        withStatedSources(repaired, doc && typeof doc.method === "string" && typeof doc.path === "string" && Array.isArray(doc.spec?.responses) ? [doc as Parameters<typeof withStatedSources>[1][number]] : []);
        return { verdict: "fixed", reason: out.reason, spec: repaired };
    }
    return { verdict: out.verdict === "app_defect" ? "app_defect" : "unfixable", reason: out.reason };
}

/** The fields of an API step that hold an object with free keys (a record; the answer gives them as pairs or JSON text). */
const recordKeys = (s: Step): readonly string[] => (s.action === "request" ? ["body", "query", "headers", "extract"] : s.action === "assertResponse" && s.check === "matchesSchema" ? ["schema"] : []);
const isEmpty = (v: unknown) => v === undefined || (typeof v === "object" && v !== null && !Array.isArray(v) && Object.keys(v).length === 0);

/**
 * A repaired API test keeps the original's records where the answer gives them empty or leaves them out, so a repair never drops what the
 * test sends or checks in silence (before the answer could give them, a real Haiku repair sent the request with body {}). Steps are
 * paired in order among those of the same kind (the requests; the matchesSchema checks).
 */
function keepRecords(original: Step[], proposed: Step[]): Step[] {
    const kind = (s: Step) => (s.action === "assertResponse" ? `${s.action}:${s.check}` : s.action);
    const seen = new Map<string, number>();
    return proposed.map((s) => {
        const keys = recordKeys(s);
        if (!keys.length) return s;
        const n = seen.get(kind(s)) ?? 0;
        seen.set(kind(s), n + 1);
        const was = original.filter((o) => kind(o) === kind(s))[n] as Record<string, unknown> | undefined;
        if (!was) return s;
        const out: Record<string, unknown> = { ...s };
        for (const k of keys) if (isEmpty(out[k]) && !isEmpty(was[k])) out[k] = was[k];
        return out as Step;
    });
}

/**
 * Structural guard on LLM API repairs ("never loosen an assertion" must not rely on the prompt alone).
 * A repair may change expected values, but must keep the same requests (method, path, auth mode), keep at
 * least as many response assertions, and may not change the expected status of security/auth tests.
 * Returns a reason when the proposal is rejected.
 */
export function weakensApiTest(original: TestSpec, proposed: Step[]): string | undefined {
    const reqs = (steps: Step[]) =>
        steps.filter((s): s is Extract<Step, { action: "request" }> => s.action === "request").map((s) => `${s.method} ${s.path} auth=${s.auth}`);
    const before = reqs(original.steps);
    const after = reqs(proposed);
    if (before.join("|") !== after.join("|")) return "requests changed (method, path or auth mode)";
    const asserts = (steps: Step[]) => steps.filter((s): s is Extract<Step, { action: "assertResponse" }> => s.action === "assertResponse");
    if (asserts(proposed).length < asserts(original.steps).length) return "response assertions removed";
    if (original.type === "security" || original.tags.includes("auth")) {
        const statuses = (steps: Step[]) =>
            asserts(steps)
                .filter((s) => s.check === "status" || s.check === "statusClass" || s.check === "statusBelow")
                .map((s) => `${s.check}=${s.expected}`)
                .join("|");
        if (statuses(original.steps) !== statuses(proposed)) return "expected status of a security test changed";
    }
    return undefined;
}

type AssertStep = Extract<Step, { action: "assert" }>;
/** A check the original may be replaced with: the same, or one that proves strictly more. */
const STRICTER: Partial<Record<AssertStep["check"], readonly AssertStep["check"][]>> = { text: ["exactText"] };
/** Checks that pass when the shown text contains `expected`: a longer expected value is stricter, a shorter one wider. */
const CONTAINS = new Set<AssertStep["check"]>(["text", "url", "title", "accessibleErrorMessage"]);

/** Why `after` checks less than `before` (same source), or undefined when it checks at least as much. Locators may change. */
function loosening(before: AssertStep, after: AssertStep): string | undefined {
    if (after.check !== before.check && !STRICTER[before.check]?.includes(after.check)) return `check ${before.check} → ${after.check}`;
    if (after.name !== before.name || after.compare !== before.compare) return "its name or comparison changed";
    if (before.expected === undefined) return undefined;
    if (after.expected === undefined) return "its expected value was dropped";
    const was = String(before.expected);
    const now = String(after.expected);
    if (was === now) return undefined;
    if (CONTAINS.has(before.check) && now.includes(was)) return undefined;
    if (before.check === "notText" && after.check === "notText" && was.includes(now)) return undefined;
    return `expected ${JSON.stringify(before.expected)} → ${JSON.stringify(after.expected)}`;
}

/** An action step's identity for "did the check move before it": what it does and to what (a re-located action is a new step). */
const stepKey = (s: Step) => JSON.stringify({ ...s, description: undefined });

/**
 * Structural guard on web repairs, like weakensApiTest: a re-written test keeps every sourced check (a stated expectation) with the
 * same source, no looser (same or stricter check, same or narrower expected value), and after the step it depended on (the last
 * non-check step before it, when the re-written test still has that step). Unsourced checks may change. Returns a reason when refused.
 */
export function weakensWebTest(original: TestSpec, proposed: Step[]): string | undefined {
    const asserts = (steps: Step[]) => steps.flatMap((s, i) => (s.action === "assert" ? [{ s, i }] : []));
    const after = asserts(proposed);
    for (const { s: before, i } of asserts(original.steps)) {
        if (!before.source) continue;
        const kept = after.find(({ s }) => s.source === before.source);
        if (!kept) {
            const same = after.some(({ s }) => s.check === before.check && JSON.stringify(s.locator) === JSON.stringify(before.locator));
            return same ? `sourced check ${before.source}: its source was changed or dropped` : `sourced check ${before.source} was removed`;
        }
        const why = loosening(before, kept.s);
        if (why) return `sourced check ${before.source} was loosened (${why})`;
        const dep = original.steps.slice(0, i).reverse().find((s) => s.action !== "assert");
        if (dep) {
            const at = proposed.findIndex((s) => stepKey(s) === stepKey(dep));
            if (at > kept.i) return `sourced check ${before.source} was moved before the step it depended on`;
        }
    }
    return undefined;
}
